settings.markdownTextFunction:
let image = data[0].image ? true : false;
let status = data[0].status == "true" ? true : false;
let signal = "signal0";
let lastActivityTime = data[0].lastActivityTime ? moment(data[0].lastActivityTime).format("DD.MM.yyyy HH:mm") : "No Data";

if(data[0].rssi && data[0].rssi <= -110){
    signal = "signal1";
} else if(data[0].rssi && data[0].rssi > -110 && data[0].rssi <= -90){
    signal = "signal2";
} else if(data[0].rssi && data[0].rssi > -90 && data[0].rssi <= -70){
    signal = "signal3";
} else if(data[0].rssi && data[0].rssi >= -70){
    signal = "signal4";
} else {
    signal = "signal0";
}

return `<div class="mainDiv">
            <div class="imageBlock">
                <img *ngIf="${!image}" style="width: 100%;" src="/api/images/public/sPIgl4qFR8WC2poGYgNjWEi9zZrpoG7O" alt="Device Image Container.png" />
                <img *ngIf="${image}" style="width: 90%" src="${data[0].image}"/>
            </div>
            <div class="infoBlock bb">
                <div class="row between">
                    <span class="key">Working status</span>
                    <span *ngIf="${!status}" class="inactive">INACTIVE</span>
                    <span *ngIf="${status}" class="active">ACTIVE</span>
                </div>
                <div class="row between">
                    <span class="key">Signal</span>
                    <img [src]="'/api/images/tenant/Frame 1618873822.png' | image | async" />
                    <img *ngIf="${signal} == 'signal4' && ${status}" src="/api/images/public/tLokfg0I4nb2ETooeShOrH6UmPjdDQHZ" alt="signal4.png" />
                    <img *ngIf="${signal} == 'signal3' && ${status}" src="/api/images/public/i1b1qZ2fJrrKJSFBXZW65EB4oyc70tKq" alt="signal3.png" />
                    <img *ngIf="${signal} == 'signal2' && ${status}" src="/api/images/public/ccCDzpLw5oPcxpgi5eLLgHq6KOHFHJLs" alt="signal2.png" />
                    <img *ngIf="${signal} == 'signal1' && ${status}" src="/api/images/public/7nCOXUUtSozVGPETHcC1rxNWpam3Z8ky" alt="signal1.png" />
                    <div *ngIf="${signal} == 'signal0' || ${!status}"  style="display: flex; align-items:center; gap: 2px;">
                        <img src="/api/images/public/eJr7dgyazfLjH7Au4ZHAHp1grHVJAACb" alt="noSignal.png" />
                        <span style="font-weight: 500; color: #667085;">No signal</span>
                    </div>
                </div>
                <div class="row between">
                    <span class="key">Last activity</span>
                    <b class="value">${lastActivityTime}</b>
                </div>
            </div>
            <div class="infoBlock">
                <div class="row between">
                    <span class="key">Type</span>
                    <b class="value">${data[0].Type}</b>
                </div>
                <div class="row between">
                    <span class="key">Model number</span>
                    <b class="value">${data[0].modelNumber}</b>
                </div>
                <div class="row between">
                    <span class="key">S/N</span>
                    <b class="value">${data[0].serialNumber}</b>
                </div>
                <div class="row between">
                    <span class="key">Department</span>
                    <b class="value">${data[0].department}</b>
                </div>
            </div>
            <div class="descriptionBlock">
                <span class="text">${data[0].description}</span>
            </div>
        </div>`;

