function openEditEntityDialog() {
    customDialog.customDialog(htmlTemplate, EditEntityDialogController).subscribe();
}

function EditEntityDialogController(instance) {
    let vm = instance;

    vm.form = vm.fb.group({
        date: [widgetContext.dashboard.dashboardTimewindow.history.fixedTimewindow ? widgetContext.dashboard.dashboardTimewindow.history.fixedTimewindow : null]
    });

    vm.cancel = function() {
        vm.dialogRef.close(null);
    };

    vm.save = function() {
        widgetContext.dashboard.onUpdateTimewindow(vm.form.value.date.startTimeMs, vm.form.value.date.endTimeMs, 0);
        vm.dialogRef.close(null);
    };
}

